export const faults={
 link:{system:'chain',label:'Eslabón rápido sin cerrar',evidence:'La unión presenta separación y no está enclavada por ambos lados.',repair:'Cerrar el eslabón compatible',explain:'La cadena necesita continuidad y un cierre completamente asentado. En una bici real verifica referencia, orientación y permiso de reutilización.'},
 stiff:{system:'chain',label:'Articulación rígida',evidence:'Un eslabón no articula libremente al pasar por la roldana.',repair:'Rehacer la unión rígida con repuesto compatible',explain:'Una articulación rígida provoca un salto periódico. Una placa o un pin dañados requieren una unión admitida por el fabricante, no forzarlos.'},
 slack:{system:'brake',label:'Exceso de holgura del cable',evidence:'En este freno mecánico la maneta recorre demasiado antes de acercar la pastilla móvil.',repair:'Ajustar la holgura del cable',explain:'Primero se comprueban cable, funda, anclaje y ajuste de pastillas; la tensión se regula según el cáliper. No confundir con un freno hidráulico.'},
 alignment:{system:'brake',label:'Cáliper desalineado',evidence:'Una pastilla roza de forma continua aunque la maneta esté libre; la rueda está correctamente asentada y el rotor recto en este caso.',repair:'Centrar el cáliper según su diseño',explain:'La alineación debe dejar paso libre al rotor y contacto adecuado. La técnica concreta depende de qué pastillas se mueven y del manual.'},
 contamination:{system:'brake',label:'Superficies de fricción contaminadas',evidence:'La maneta tiene recorrido normal y las pastillas contactan, pero el par de frenado es bajo. La película coloreada en 3D representa contaminación.',repair:'Sustituir pastillas contaminadas y limpiar el rotor',explain:'Este caso requiere pastillas nuevas y limpieza del rotor con el producto autorizado. Tensar más el cable no restaura la fricción. Después se verifica y asienta según fabricante.'}
};
export function createWorkshop(mode='guided',random=Math.random){return {id:crypto.randomUUID(),mode,faults:mode==='guided'?['link','slack']:[random()<.5?'link':'stiff',['slack','alignment','contamination'][Math.min(2,Math.floor(random()*3))]],fixed:[],inspected:[],events:[],hints:0,errors:0,done:false,feedback:'',hintUsed:false};}
export const workshopScore=s=>Math.max(0,100-s.errors*15-s.hints*10);
export function workshopAct(s,action,id){if(s.done)return false;if(action==='inspect'&&['chain','brake'].includes(id)){if(!s.inspected.includes(id))s.inspected.push(id);s.feedback=s.faults.filter(f=>faults[f].system===id&&!s.fixed.includes(f)).map(f=>faults[f].evidence).join(' ')||'No quedan síntomas de este sistema en la simulación.';return true;}
 if(action==='hint'){if(s.hintUsed)return false;s.hintUsed=true;s.hints++;const f=s.faults.find(f=>!s.fixed.includes(f));s.feedback=f?faults[f].explain:'Comprueba ambos sistemas para cerrar el trabajo.';return true;}
 if(action==='repair'&&faults[id]){if(!s.inspected.includes(faults[id].system)){s.feedback='Inspecciona este sistema antes de elegir una intervención.';return false;}const good=s.faults.includes(id)&&!s.fixed.includes(id);if(good){s.fixed.push(id);s.hintUsed=false;}else s.errors++;s.events.push({action,id,good});s.feedback=good?'Intervención aplicada. Observa el cambio y comprueba los sistemas.':'Intervención innecesaria o repetida: no corrige una causa pendiente. −15 puntos.';return true;}
 if(action==='verify'){const good=s.faults.every(f=>s.fixed.includes(f))&&['chain','brake'].every(x=>s.inspected.includes(x));s.events.push({action,good});if(good)s.done=true;else s.errors++;s.feedback=good?'Ambos sistemas pasan la verificación simulada. En una bicicleta real faltan los controles de montaje, par, cierre y prueba segura del fabricante.':'Todavía quedan síntomas o sistemas sin inspeccionar. −15 puntos. Revisa continuidad y articulación de cadena, recorrido, roce y fuerza del freno.';return true;}return false;}
export function workshopState(s){const pending=s.faults.filter(f=>!s.fixed.includes(f));return {open:pending.includes('link'),stiff:pending.includes('stiff'),slack:pending.includes('slack'),alignment:pending.includes('alignment'),contamination:pending.includes('contamination')};}
